import { readFile, readdir } from "node:fs/promises";
import path from "node:path";

// Renders rules/*.md into the per-tool instruction files each AI coding
// environment reads.
//
// This lives in a library because two callers need it against two different
// output roots: scripts/compile-rules.mjs regenerates the copies committed to
// this repository, and bin/cli.mjs writes them into a consumer's project. A
// second implementation would drift from the first, which is the failure this
// kit exists to prevent.

export const GENERATED_NOTE =
  "<!-- Generated by scripts/compile-rules.mjs from rules/. Do not edit directly. -->";

// Rules that are also published as skill reference pages, so the skill can link
// to the full text without duplicating it.
export const REFERENCE_EXPORTS = new Map([
  ["40-accessibility.md", "accessibility.md"],
  ["50-security.md", "security.md"],
]);

export const TARGETS = [
  {
    file: "CLAUDE.md",
    heading: "UCSD Decorator — project rules for Claude Code",
    intro:
      "These rules apply when generating, modifying, or reviewing code in a UC San Diego Decorator project. The canonical source is `rules/`; the full skill lives in `skills/ucsd-decorator/`.",
  },
  {
    file: "AGENTS.md",
    heading: "UCSD Decorator — agent instructions",
    intro:
      "These rules apply to any agent generating, modifying, or reviewing code in a UC San Diego Decorator project. The canonical source is `rules/`.",
  },
  {
    file: ".cursorrules",
    heading: "UCSD Decorator — project rules",
    intro:
      "These rules apply when generating, modifying, or reviewing code in a UC San Diego Decorator project.",
  },
  {
    file: ".github/copilot-instructions.md",
    heading: "UCSD Decorator — custom instructions",
    intro:
      "These rules apply when generating, modifying, or reviewing code in a UC San Diego Decorator project.",
  },
];

export function stripFrontmatter(source) {
  const match = /^---\n([\s\S]*?)\n---\n?/.exec(source);
  if (!match) return { data: {}, body: source.trim() };
  const data = {};
  for (const line of match[1].split("\n")) {
    const separator = line.indexOf(":");
    if (separator === -1) continue;
    data[line.slice(0, separator).trim()] = line.slice(separator + 1).trim();
  }
  return { data, body: source.slice(match[0].length).trim() };
}

/** Push every heading in a rule body down one level so it nests under its title. */
export function demoteHeadings(body) {
  return body.replace(/^(#{1,5}) /gm, (_, hashes) => `${hashes}# `);
}

export async function readRules(rulesDir) {
  const filenames = (await readdir(rulesDir)).filter((name) => name.endsWith(".md")).sort();
  if (!filenames.length) throw new Error(`${rulesDir} contains no markdown files.`);
  const rules = [];
  for (const filename of filenames) {
    const { data, body } = stripFrontmatter(await readFile(path.join(rulesDir, filename), "utf8"));
    if (!data.title) throw new Error(`rules/${filename} is missing a frontmatter title.`);
    rules.push({ filename, title: data.title, body });
  }
  return rules;
}

function render(target, rules, note) {
  const sections = rules.map((rule) => `## ${rule.title}\n\n${demoteHeadings(rule.body)}`);
  return [
    note,
    "",
    `# ${target.heading}`,
    "",
    target.intro,
    "",
    "---",
    "",
    sections.join("\n\n---\n\n"),
    "",
  ].join("\n");
}

/**
 * Render every generated file as a Map of repo-relative path to contents.
 *
 * @param {object}   options
 * @param {string}   options.rulesDir      directory holding rules/*.md
 * @param {string}  [options.note]         the generated-by comment to stamp in.
 *   Consumer projects pass a version-stamped note so `check` fails after the kit
 *   is upgraded; this repository's own copies keep the unversioned default, or a
 *   version bump would dirty four committed files and destabilize `npm test`.
 * @param {string[]}[options.exclude]      target filenames to skip. `add` passes
 *   ["AGENTS.md"] — see bin/cli.mjs for why that one is never written.
 * @param {boolean} [options.references]   also render the exported skill pages.
 */
export async function renderRuleFiles({
  rulesDir,
  note = GENERATED_NOTE,
  exclude = [],
  references = false,
} = {}) {
  const rules = await readRules(rulesDir);
  const outputs = new Map();

  for (const target of TARGETS) {
    if (exclude.includes(target.file)) continue;
    outputs.set(target.file, render(target, rules, note));
  }

  if (references) {
    for (const [source, destination] of REFERENCE_EXPORTS) {
      const rule = rules.find((entry) => entry.filename === source);
      if (!rule) throw new Error(`REFERENCE_EXPORTS names rules/${source}, which does not exist.`);
      outputs.set(
        path.posix.join("skills/ucsd-decorator/references", destination),
        `${note}\n\n# ${rule.title}\n\n${rule.body}\n`,
      );
    }
  }

  return { rules, outputs };
}
